import os

# Search for submissions and config files
runs_dir = '/home/USER/runs'

def search_directory(path, patterns, max_depth=5, current_depth=0):
    """Recursively search for files matching patterns"""
    results = []
    if current_depth > max_depth:
        return results

    try:
        entries = os.listdir(path)
    except PermissionError:
        return results

    for entry in sorted(entries):
        full_path = os.path.join(path, entry)
        rel_path = os.path.relpath(full_path, runs_dir)

        if any(p in rel_path for p in patterns):
            results.append(full_path)

        if os.path.isdir(full_path):
            results.extend(search_directory(full_path, patterns, max_depth, current_depth + 1))

    return results

# Search for submission-related files
patterns = ['submit', 'action', 'config', 'input', 'output', 'test', 'task']
